/**
 * T1 — Census tests for snappea-wasm
 *
 * Validates the WASM kernel against SnapPy reference data for 15
 * census manifolds spanning 2–7 tetrahedra, 1–3 cusps, and various
 * homology groups.
 *
 * Reference values generated by SnapPy 3.3.
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { readFileSync } from 'fs';
import { join } from 'path';

const FIXTURES = join(__dirname, '../fixtures');
const reference = JSON.parse(
  readFileSync(join(__dirname, '../reference/census_reference.json'), 'utf-8')
);

let kernel;

beforeAll(async () => {
  const mod = await import('../../dist/index.js');
  const init = mod.init || mod.default?.init;
  kernel = await init();
});

afterAll(() => {
  if (kernel) kernel.destroy();
});

/**
 * Helper: load a triangulation, compute structure, return tri pointer.
 */
function loadManifold(name) {
  const data = readFileSync(join(FIXTURES, `${name}.tri`), 'utf-8');
  const tri = kernel.triangulationFromString(data);
  kernel.findCompleteHyperbolicStructure(tri);
  return tri;
}

// ── T1.1 — Parse all census fixtures ────────────────────────────────

describe('T1.1 — Parse census manifolds', () => {
  for (const ref of reference) {
    it(`should parse ${ref.canonical_name}`, () => {
      const tri = loadManifold(ref.canonical_name);
      expect(tri).toBeTruthy();
      expect(tri).not.toBe(0);
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.2 — Tetrahedra count ─────────────────────────────────────────

describe('T1.2 — Tetrahedra counts', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} has ${ref.num_tetrahedra} tetrahedra`, () => {
      const tri = loadManifold(ref.canonical_name);
      expect(kernel.getNumTetrahedra(tri)).toBe(ref.num_tetrahedra);
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.3 — Cusp count ───────────────────────────────────────────────

describe('T1.3 — Cusp counts', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} has ${ref.num_cusps} cusps`, () => {
      const tri = loadManifold(ref.canonical_name);
      expect(kernel.getNumCusps(tri)).toBe(ref.num_cusps);
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.4 — Volume ───────────────────────────────────────────────────

describe('T1.4 — Volume computation', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} volume ≈ ${ref.volume}`, () => {
      const tri = loadManifold(ref.canonical_name);
      expect(kernel.volume(tri)).toBeCloseTo(ref.volume, 6);
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.5 — Solution type ────────────────────────────────────────────

describe('T1.5 — Solution type (geometric)', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} has geometric solution`, () => {
      const tri = loadManifold(ref.canonical_name);
      expect(kernel.solutionType(tri)).toBe('geometric');
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.6 — Orientability ────────────────────────────────────────────

describe('T1.6 — Orientability', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} is ${ref.orientability}`, () => {
      const tri = loadManifold(ref.canonical_name);
      const expected = ref.orientability === 'oriented' ? 'orientable' : 'nonorientable';
      expect(kernel.getOrientability(tri)).toBe(expected);
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.7 — Fundamental group ────────────────────────────────────────

describe('T1.7 — Fundamental group', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} has ${ref.num_generators} generators`, () => {
      const tri = loadManifold(ref.canonical_name);
      const fg = kernel.fundamentalGroup(tri);
      expect(fg.num_generators).toBe(ref.num_generators);
      expect(fg.relations.length).toBe(ref.num_relators);
      kernel.freeTriangulation(tri);
    });
  }
});

// ── T1.8 — Round-trip serialization ─────────────────────────────────

describe('T1.8 — Round-trip serialization', () => {
  for (const ref of reference) {
    it(`${ref.canonical_name} survives serialization round-trip`, () => {
      const tri = loadManifold(ref.canonical_name);
      const serialized = kernel.triangulationToString(tri);
      expect(serialized).toContain('Triangulation');

      const tri2 = kernel.triangulationFromString(serialized);
      kernel.findCompleteHyperbolicStructure(tri2);

      expect(kernel.getNumTetrahedra(tri2)).toBe(ref.num_tetrahedra);
      expect(kernel.getNumCusps(tri2)).toBe(ref.num_cusps);
      expect(kernel.volume(tri2)).toBeCloseTo(ref.volume, 6);

      kernel.freeTriangulation(tri);
      kernel.freeTriangulation(tri2);
    });
  }
});

// ── T1.9 — Copy preserves invariants ────────────────────────────────

describe('T1.9 — Copy preserves invariants', () => {
  const subset = reference.filter(r =>
    ['m004', 'm129', 's776', 'v1539'].includes(r.canonical_name)
  );
  for (const ref of subset) {
    it(`copy of ${ref.canonical_name} has same volume`, () => {
      const tri = loadManifold(ref.canonical_name);
      const copy = kernel.copyTriangulation(tri);

      expect(copy).not.toBe(tri);
      expect(kernel.volume(copy)).toBeCloseTo(ref.volume, 6);
      expect(kernel.getNumCusps(copy)).toBe(ref.num_cusps);

      kernel.freeTriangulation(tri);
      kernel.freeTriangulation(copy);
    });
  }
});

// ── T1.10 — Cusp topology ───────────────────────────────────────────

describe('T1.10 — Cusp topology', () => {
  const subset = reference.filter(r =>
    ['m004', 'm129', 's596', 's776'].includes(r.canonical_name)
  );
  for (const ref of subset) {
    it(`${ref.canonical_name} cusps are torus cusps`, () => {
      const tri = loadManifold(ref.canonical_name);
      for (let i = 0; i < ref.num_cusps; i++) {
        expect(kernel.getCuspTopology(tri, i)).toBe('torus');
      }
      kernel.freeTriangulation(tri);
    });
  }
});
